public class MainActivity extends Activity implements LocationListener {
 final String[] sections={"Inicio","Instrumentos","Gráficas","Energía","Telemetría real","Viajes GPS","Prestaciones","Radio","TV / TDT","Web / YouTube","Aplicaciones","Android Auto","Apple CarPlay","Sensores","Cámaras","Historial","Configuración","Actualizaciones"};
 final String[] models={"C10 REEV","C10 eléctrico","C10 Pro Max","B10","T03","Otro Leapmotor"};
 final int[] accents={0xff22d3ee,0xff22c55e,0xff60a5fa,0xfff59e0b,0xfff87171,0xffc084fc};
 RadioAudio radio; MediaCenter mediaCenter;
 final java.util.ArrayList<TextView> radioViews=new java.util.ArrayList<>();
 final java.util.ArrayList<SpeedGraph> graphs=new java.util.ArrayList<>();
 final java.util.ArrayList<SpeedGraph.Point> speedHistory=new java.util.ArrayList<>();
 final Handler handler=new Handler(Looper.getMainLooper());
 android.content.SharedPreferences prefs; LinearLayout root,body,nav; TextView status; LocationManager lm; Location fix; long fixAt; boolean parked=false,split=false,active=false; String primary="Inicio",secondary="Instrumentos"; int bg,card,fg,accent; float font; int ratio=50; ArrayList<TextView> live=new ArrayList<>(); ArrayList<WebView> browsers=new ArrayList<>(); Performance performance; String perfStatus="Sin prueba activa"; String pendingReport=""; final int EXPORT=401; VehicleSignals signals; CloudReader cloud=new CloudReader(); String cloudText="Sin conexión configurada"; String cloudHost=""; String cloudToken=""; String cloudEntities=""; boolean cloudBusy=false; TripMeter trip=new TripMeter(); ArrayList<TextView> signalViews=new ArrayList<>(),tripViews=new ArrayList<>(),cloudViews=new ArrayList<>();
 int dp(float x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 String model(){return prefs.getString("model",models[0]);}
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("c10",MODE_PRIVATE);lm=(LocationManager)getSystemService(LOCATION_SERVICE);split=prefs.getBoolean("split",false);ratio=prefs.getInt("ratio",50);primary=prefs.getString("primary","Inicio");secondary=prefs.getString("secondary","Instrumentos"); signals=new VehicleSignals(this);radio=new RadioAudio(this);mediaCenter=new MediaCenter(this);render();}
 @Override protected void onResume(){super.onResume();active=true;render();signals.start();startGPS();handler.removeCallbacks(tick);handler.post(tick);}
 @Override protected void onPause(){active=false;parked=false;mediaCenter.close();radio.stop();signals.stop();trip.gap();stopGPS();handler.removeCallbacks(tick);super.onPause();}
 @Override protected void onDestroy(){clearBrowsers();radio.stop();handler.removeCallbacks(tick);super.onDestroy();}
 final Runnable tick=new Runnable(){public void run(){if(!active)return;if(mediaCenter.busy()){toast("Detén el vídeo antes de escuchar radio");return;}if(parked&&!stationary()){parked=false;render();}refreshLive();handler.postDelayed(this,500);}};
 boolean gpsAllowed(){return checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED;}
 @android.annotation.SuppressLint("MissingPermission") void startGPS(){if(!gpsAllowed())return;try{lm.requestLocationUpdates(LocationManager.GPS_PROVIDER,500,0,this);}catch(Exception e){}}
 void stopGPS(){try{lm.removeUpdates(this);}catch(Exception e){}fix=null;fixAt=0;}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==17){startGPS();refreshLive();}}
 void askGPS(){requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},17);}
 boolean fresh(){return fix!=null&&SystemClock.elapsedRealtime()-fixAt<3500&&fix.hasSpeed()&&fix.hasAccuracy()&&fix.getAccuracy()<=25;}
 boolean stationary(){return fresh()&&fix.getSpeed()<0.5f;}
 boolean samsungHandheld(){android.app.UiModeManager ui=(android.app.UiModeManager)getSystemService(UI_MODE_SERVICE);return "samsung".equalsIgnoreCase(Build.MANUFACTURER)&&"SM-G991N".equalsIgnoreCase(Build.MODEL)&&getPackageManager().hasSystemFeature(PackageManager.FEATURE_TELEPHONY)&&!getPackageManager().hasSystemFeature(PackageManager.FEATURE_AUTOMOTIVE)&&ui!=null&&ui.getCurrentModeType()!=android.content.res.Configuration.UI_MODE_TYPE_CAR;}
 boolean videoAllowed(){return active&&(samsungHandheld()||(parked&&stationary()));}
 @Override public void onLocationChanged(Location l){fix=l;fixAt=l.getElapsedRealtimeNanos()/1000000;if(fresh()){SpeedGraph.add(speedHistory,fixAt,l.getSpeed()*3.6f);}if(fresh()&&l.getAccuracy()<=15&&(!l.hasSpeedAccuracy()||l.getSpeedAccuracyMetersPerSecond()<=1.5f))trip.sample(fixAt,l.getSpeed()*3.6);else trip.gap();if(parked&&!stationary()){parked=false;render();}if(performance!=null&&fresh()&&l.getAccuracy()<=15&&(!l.hasSpeedAccuracy()||l.getSpeedAccuracyMetersPerSecond()<=1.5f)){Double old=performance.result;performance.sample(l.getElapsedRealtimeNanos()/1000000,l.getSpeed()*3.6);perfStatus=performance.status();if(old==null&&performance.result!=null){addHistory(performance.low+"–"+performance.high+" km/h · "+perfStatus);performance=null;}}refreshLive();}
 @Override public void onProviderEnabled(String s){} @Override public void onProviderDisabled(String s){fix=null;if(parked){parked=false;render();}} @Override public void onStatusChanged(String s,int i,Bundle b){}
 void clearBrowsers(){if(mediaCenter!=null)mediaCenter.close();for(WebView w:browsers){try{w.stopLoading();w.onPause();if(w.getParent() instanceof ViewGroup)((ViewGroup)w.getParent()).removeView(w);w.destroy();}catch(Exception e){}}browsers.clear();}
 LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;} LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(10));return d;}
 TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size*font);t.setTextColor(color);t.setPadding(dp(8),dp(7),dp(8),dp(7));return t;}
 void label(LinearLayout l,String s){l.addView(text(s,15,fg));}
 void title(LinearLayout l,String s){TextView t=text(s,22,accent);t.setTypeface(null,Typeface.BOLD);l.addView(t);}
 Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(14*font);b.setTextColor(fg);b.setBackground(shape(card));b.setMinHeight(dp(44));b.setOnClickListener(v->action.run());return b;}
 void btn(LinearLayout l,String s,Runnable r){Button b=button(s,r);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(dp(3),dp(3),dp(3),dp(3));l.addView(b,lp);}
 void pair(LinearLayout l,String a,Runnable ar,String b,Runnable br){LinearLayout r=row();for(Button x:new Button[]{button(a,ar),button(b,br)}){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(3),dp(3),dp(3),dp(3));r.addView(x,lp);}l.addView(r);}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 void render(){clearBrowsers();radioViews.clear();graphs.clear();live.clear();signalViews.clear();tripViews.clear();cloudViews.clear();prefs.edit().putString("primary",primary).putString("secondary",secondary).apply();boolean day=prefs.getBoolean("day",false);bg=day?0xffe7eef5:0xff09111e;card=day?0xffcbdbea:0xff172c45;fg=day?0xff102236:0xffe9f3ff;accent=accents[Math.max(0,Math.min(accents.length-1,prefs.getInt("accent",0)))];if(day)accent=0xff075985;font=prefs.getFloat("font",1f);
 root=col();root.setBackgroundColor(bg);root.setPadding(dp(8),dp(4),dp(8),dp(4));setContentView(root);if(Build.VERSION.SDK_INT>=35){root.setOnApplyWindowInsetsListener((v,insets)->{android.graphics.Insets safe=insets.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout());v.setPadding(dp(8)+safe.left,dp(4)+safe.top,dp(8)+safe.right,dp(4)+safe.bottom);return insets;});root.requestApplyInsets();}LinearLayout head=row();TextView brand=text("C10 CONTROL PRO  ·  Leapmotor Guía",19,accent);brand.setTypeface(null,Typeface.BOLD);head.addView(brand,new LinearLayout.LayoutParams(0,-2,1));status=text("",13,fg);head.addView(status);head.addView(button(split?"Pantalla completa":"Dividir pantalla",()->{split=!split;prefs.edit().putBoolean("split",split).apply();render();}));root.addView(head);
 HorizontalScrollView hs=new HorizontalScrollView(this);nav=row();hs.addView(nav);for(String s:sections){Button b=button(s,()->{primary=s;render();});if(s.equals(primary))b.setTextColor(accent);nav.addView(b);}root.addView(hs,new LinearLayout.LayoutParams(-1,dp(50)));
 body=row();root.addView(body,new LinearLayout.LayoutParams(-1,0,1));addPanel(primary,false,split?ratio:100);if(split)addPanel(secondary,true,100-ratio);refreshLive();}
 void addPanel(String page,boolean right,int weight){LinearLayout shell=col();shell.setPadding(dp(4),dp(4),dp(4),dp(4));body.addView(shell,new LinearLayout.LayoutParams(0,-1,weight));if(split){Button choose=button((right?"Derecha: ":"Izquierda: ")+page,()->new AlertDialog.Builder(this).setTitle("Elegir panel").setItems(sections,(d,n)->{if(right)secondary=sections[n];else primary=sections[n];render();}).show());shell.addView(choose);}
 if(page.equals("TV / TDT")||page.equals("Web / YouTube")||page.equals("Aplicaciones")){mediaCenter.show(shell,page);return;}ScrollView sv=new ScrollView(this);LinearLayout content=col();sv.addView(content);shell.addView(sv,new LinearLayout.LayoutParams(-1,0,1));title(content,page);switch(page){
 case "Inicio":label(content,model()+" · Perfil local, no leído del coche");if(model().equals(models[0]))label(content,"Batería nominal de referencia: 28,4 kWh · 215 CV");label(content,"Batería actual / combustible / autonomía: consulta Telemetría real. Sin fuente conectada no hay medición");live(content);pair(content,"Instrumentos",()->go("Instrumentos"),"Telemetría real",()->go("Telemetría real"));pair(content,"Viajes GPS",()->go("Viajes GPS"),"Configuración",()->go("Configuración"));break;
 case "Instrumentos":graph(content,true);live(content);btn(content,"Permitir GPS",this::askGPS);label(content,"Potencia motor, SOC, temperaturas y regeneración: no comprobados");break;
 case "Radio":radioPanel(content);break;
 case "Gráficas":graph(content,false);label(content,"Velocidad GPS · últimos 120 segundos · huecos sin señal no se unen. Potencia y regeneración: sin fuente verificada.");break;
 case "Telemetría real":telemetryPanel(content);break;
 case "Viajes GPS":tripPanel(content);break;
 case "Energía":label(content,"Sin fuente BMS/CAN validada. No se muestran ceros ficticios.");label(content,"Energía gastada · regenerada · generada · combustible: —");energyForm(content);break;
 case "Prestaciones":live(content);label(content,"Pruebas únicamente en circuito cerrado. GPS estimado, no velocímetro homologado.");for(int h:new int[]{50,100,120,140})btn(content,"0–"+h+" km/h",()->arm(0,h));btn(content,"80–120 km/h (80 ±1,5 durante 3 s)",()->arm(80,120));btn(content,"Cancelar / reiniciar prueba",()->{performance=null;perfStatus="Cancelada";refreshLive();});break;
 case "Aplicaciones":break;
 case "Android Auto":case "Apple CarPlay":label(content,"Motor de proyección propio: aún no implementado. Diagnóstico local real; no se reclama USB ni se inicia un hotspot.");label(content,ConnectionAudit.report(this));btn(content,"Actualizar estado",this::render);btn(content,"Exportar informe",this::export);btn(content,"Permitir ubicación",this::askGPS);break;
 case "Sensores":label(content,diagnostic());btn(content,"Actualizar informe",this::render);btn(content,"Exportar informe TXT",this::export);btn(content,"Permitir GPS",this::askGPS);break;
 case "Cámaras":label(content,cameras());label(content,"Cámara 360°, frontal OEM y modo centinela: integración no comprobada. No se modifican servicios del vehículo.");break;
 case "Historial":label(content,prefs.getString("history","Sin registros"));btn(content,"Borrar historial",()->new AlertDialog.Builder(this).setMessage("¿Borrar historial local?").setPositiveButton("Borrar",(d,w)->{prefs.edit().remove("history").apply();render();}).setNegativeButton("Cancelar",null).show());break;
 case "Configuración":settings(content);break;
 case "Actualizaciones":label(content,"Versión 6.3 · multimedia · paquete com.leapmotorguia.c10control.lab3");label(content,"No hay servidor de actualización configurado. Las versiones necesitan el mismo certificado de firma; esta prueba utiliza una firma de laboratorio; no garantiza actualización de la 3.0.");btn(content,"Exportar diagnóstico",this::export);break;
 }}
 void graph(LinearLayout l,boolean gauge){SpeedGraph g=new SpeedGraph(this,card,fg,accent,gauge);graphs.add(g);l.addView(g,new LinearLayout.LayoutParams(-1,dp(210)));}
 void go(String s){primary=s;render();} void live(LinearLayout l){TextView t=text("",20,fg);live.add(t);l.addView(t);} void refreshLive(){String speed=fresh()?String.format(Locale.US,"%.1f km/h",fix.getSpeed()*3.6):"GPS sin dato válido";if(status!=null)status.setText(speed+"  ·  "+(videoAllowed()?"Vídeo autorizado manualmente":"Vídeo bloqueado"));for(TextView t:live)t.setText(speed+"\n"+perfStatus);for(TextView t:signalViews)t.setText(signals.report());for(TextView t:tripViews)t.setText(trip.summary());for(TextView t:cloudViews)t.setText(cloudText);for(TextView t:radioViews)t.setText(radio.status());for(SpeedGraph g:graphs)g.update(speedHistory,fresh()?fix.getSpeed()*3.6f:null,SystemClock.elapsedRealtime());}
 void arm(int lo,int hi){if(!gpsAllowed()){askGPS();return;}new AlertDialog.Builder(this).setMessage("¿Prueba en recinto cerrado y seguro?").setPositiveButton("Preparar",(d,w)->{performance=new Performance(lo,hi);perfStatus="Esperando inicio "+lo+"–"+hi;refreshLive();}).setNegativeButton("Cancelar",null).show();}
 void parkedPrompt(){if(samsungHandheld()){render();return;}if(!gpsAllowed()){askGPS();return;}if(!stationary()){toast("Necesitas una señal GPS reciente y velocidad prácticamente cero. El GPS no confirma la posición P.");return;}new AlertDialog.Builder(this).setTitle("Solo estacionado").setMessage("Confirma que el vehículo está estacionado en P y con freno de estacionamiento. El GPS no puede comprobar el freno ni la posición P.").setPositiveButton("Estoy estacionado",(d,w)->{parked=stationary();render();}).setNegativeButton("Cancelar",null).show();}
 void radioPanel(LinearLayout l){label(l,"Solo audio · no requiere GPS ni confirmar estacionamiento. Elige emisora antes de iniciar la marcha o mediante el acompañante.");TextView t=text(radio.status(),20,fg);radioViews.add(t);l.addView(t);for(int i=0;i<RadioAudio.NAMES.length;i++){final int n=i;btn(l,RadioAudio.NAMES[i],()->{if(!active)return;radio.play(n);refreshLive();});}btn(l,"Detener radio",()->{radio.stop();refreshLive();});label(l,"La radio continúa al cambiar de pestaña dentro de esta app. Se detiene al salir, al perder el foco de audio o al fallar la conexión. Emisiones por Internet, pendientes de prueba en LeapOS.");}
 void settings(LinearLayout l){btn(l,"Modelo: "+model(),()->new AlertDialog.Builder(this).setItems(models,(d,n)->{prefs.edit().putString("model",models[n]).apply();render();}).show());btn(l,"Tema: "+(prefs.getBoolean("day",false)?"Día":"Noche"),()->{prefs.edit().putBoolean("day",!prefs.getBoolean("day",false)).apply();render();});String[] names={"Cian","Verde","Azul","Ámbar","Rojo","Violeta"};btn(l,"Color de acento",()->new AlertDialog.Builder(this).setItems(names,(d,n)->{prefs.edit().putInt("accent",n).apply();render();}).show());btn(l,"Tamaño de letra",()->new AlertDialog.Builder(this).setItems(new String[]{"Compacto","Normal","Grande","Extra grande"},(d,n)->{prefs.edit().putFloat("font",new float[]{.85f,1f,1.15f,1.3f}[n]).apply();render();}).show());btn(l,"División: "+ratio+" / "+(100-ratio),()->new AlertDialog.Builder(this).setItems(new String[]{"35 / 65","50 / 50","65 / 35"},(d,n)->{ratio=new int[]{35,50,65}[n];prefs.edit().putInt("ratio",ratio).apply();render();}).show());btn(l,"Permiso ubicación",this::askGPS);label(l,"Resolución y FPS de proyección: no configurables sin motor de Android Auto/CarPlay validado.");}
 String usb(){try{UsbManager u=(UsbManager)getSystemService(USB_SERVICE);StringBuilder s=new StringBuilder("USB visibles: ");for(UsbDevice d:u.getDeviceList().values())s.append("\nVID ").append(d.getVendorId()).append(" PID ").append(d.getProductId()).append(" permiso ").append(u.hasPermission(d));return s.toString()+"\nNo se reclama el dispositivo.";}catch(Exception e){return "USB: acceso no comprobado";}}
 String cameras(){try{CameraManager c=(CameraManager)getSystemService(CAMERA_SERVICE);return "IDs de cámaras Android enumerables: "+Arrays.toString(c.getCameraIdList())+" (no implica acceso a cámara OEM).";}catch(Exception e){return "Cámaras Android: acceso no comprobado";}}
 String diagnostic(){StringBuilder s=new StringBuilder("Android "+Build.VERSION.RELEASE+" (API "+Build.VERSION.SDK_INT+")\nModelo: "+Build.MODEL+"\nFabricante: "+Build.MANUFACTURER+"\nArquitecturas: "+Arrays.toString(Build.SUPPORTED_ABIS)+"\nGPS permiso: "+gpsAllowed()+"\nGPS dato válido: "+fresh()+"\n"+usb()+"\n"+cameras()+"\nSensores Android enumerables:\n");try{SensorManager m=(SensorManager)getSystemService(SENSOR_SERVICE);for(Sensor x:m.getSensorList(Sensor.TYPE_ALL))s.append(x.getName()).append(" (tipo ").append(x.getType()).append(")\n");}catch(Exception e){s.append("No comprobado\n");}try{PackageInfoDummy(s);}catch(Exception e){}s.append("\n").append(ConnectionAudit.report(this)).append("\n").append(signals.report()).append("\nBMS, CAN, TPMS, cámaras OEM, generador, puertas, clima: no comprobados.\nNo se realiza escaneo de red ni escritura de centralitas.");return s.toString();}
 void PackageInfoDummy(StringBuilder s){for(String p:new String[]{"com.headqlink.app","cn.manstep.phonemirrorBox","com.google.android.apps.maps","com.spotify.music"})s.append(p).append(": ").append(getPackageManager().getLaunchIntentForPackage(p)!=null?"lanzador visible":"no detectado").append('\n');}
 void export(){pendingReport=diagnostic();try{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/plain");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"C10-diagnostico.txt");startActivityForResult(i,EXPORT);}catch(Exception e){toast("Selector de documentos no disponible");}}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==EXPORT&&c==RESULT_OK&&d!=null&&d.getData()!=null){try(OutputStream o=getContentResolver().openOutputStream(d.getData())){o.write(pendingReport.getBytes(java.nio.charset.StandardCharsets.UTF_8));toast("Informe guardado");}catch(Exception e){toast("No se pudo guardar");}}}
 void addHistory(String s){String old=prefs.getString("history","");String value=new java.text.SimpleDateFormat("dd/MM HH:mm",Locale.getDefault()).format(new Date())+" · "+s+"\n"+old;prefs.edit().putString("history",value.substring(0,Math.min(value.length(),50000))).apply();}

 void telemetryPanel(LinearLayout l){
  label(l,"LEAPOS · diagnóstico experimental pasivo. Solo se observan mensajes que Android entregue a esta app. Los identificadores y valores son brutos, sin unidad confirmada; no se usan para decisiones de conducción.");
  TextView t=text("",14,fg);signalViews.add(t);l.addView(t);btn(l,"Reiniciar observación",()->{signals.reset();refreshLive();});btn(l,"Exportar diagnóstico local",this::export);
  label(l,"HOME ASSISTANT · lectura opcional mediante HTTPS. Requiere una instalación propia con integración Leapmotor. Nunca envía órdenes. El token se conserva solo en memoria y no se exporta.");
  EditText host=new EditText(this);host.setSingleLine(true);host.setTextColor(fg);host.setHintTextColor(fg);host.setHint("https://tu-servidor");host.setText(cloudHost);l.addView(host);
  EditText token=new EditText(this);token.setSingleLine(true);token.setInputType(129);token.setTextColor(fg);token.setHintTextColor(fg);token.setHint("Token Home Assistant");token.setText(cloudToken);l.addView(token);
  EditText entities=new EditText(this);entities.setTextColor(fg);entities.setHintTextColor(fg);entities.setHint("IDs sensor separados por coma");entities.setText(cloudEntities);l.addView(entities);
  btn(l,"Leer sensores seleccionados",()->{if(cloudBusy){toast("Lectura en curso");return;}cloudHost=host.getText().toString().trim();cloudToken=token.getText().toString().trim();cloudEntities=entities.getText().toString().trim();cloudBusy=true;cloudText="Consultando…";refreshLive();final String h=cloudHost,k=cloudToken,e=cloudEntities;new Thread(()->{String result=cloud.read(h,k,e);runOnUiThread(()->{cloudBusy=false;if(!cloudToken.equals(k)||!cloudHost.equals(h)||!cloudEntities.equals(e))return;cloudText=result;refreshLive();});}).start();});
  btn(l,"Borrar conexión y datos de sesión",()->{cloudToken="";cloudHost="";cloudEntities="";cloudText="Desconectado";render();});
  TextView out=text("",15,fg);cloudViews.add(out);l.addView(out);label(l,"La edad y la unidad proceden de Home Assistant. Un valor de nube no equivale a telemetría CAN en tiempo real.");
 }
 void tripPanel(LinearLayout l){label(l,"Distancia integrada por velocidad GPS, no cuentakilómetros OEM. Solo registra con la app visible; descarta huecos y muestras no válidas. No estima kWh, gasolina ni regeneración.");TextView t=text("",22,fg);tripViews.add(t);l.addView(t);btn(l,"Permitir GPS",this::askGPS);pair(l,"Iniciar / continuar",()->{trip.start();refreshLive();},"Pausar",()->{trip.pause();refreshLive();});pair(l,"Guardar viaje",()->{trip.pause();addHistory("VIAJE GPS · "+trip.summary().replace('\n',' '));refreshLive();toast("Guardado");},"Reiniciar",()->new AlertDialog.Builder(this).setMessage("¿Reiniciar solo este viaje GPS?").setPositiveButton("Reiniciar",(d,w)->{trip.reset();refreshLive();}).setNegativeButton("Cancelar",null).show());}

 void energyForm(LinearLayout l){String[] labels={"Distancia km","Gastados kWh","Regenerados kWh","Generador kWh","Gasolina L"};EditText[] e=new EditText[5];for(int i=0;i<5;i++){e[i]=new EditText(this);e[i].setTextColor(fg);e[i].setHintTextColor(fg);e[i].setHint(labels[i]+" (opcional)");e[i].setSingleLine(true);e[i].setInputType(8194);l.addView(e[i]);}btn(l,"Guardar registro MANUAL",()->{Double[] v=new Double[5];try{for(int i=0;i<5;i++){String s=e[i].getText().toString().trim().replace(',','.');if(!s.isEmpty()){v[i]=Double.parseDouble(s);if(!Double.isFinite(v[i])||v[i]<0)throw new Exception();}}if(v[0]==null||v[0]<=0)throw new Exception();StringBuilder s=new StringBuilder("MANUAL · ");for(int i=0;i<5;i++)s.append(labels[i]).append(": ").append(v[i]==null?"—":v[i]).append(" · ");if(v[1]!=null&&v[2]!=null)s.append("Balance tracción: ").append(v[1]-v[2]).append(" kWh · ");if(v[1]!=null&&v[2]!=null&&v[1]>0)s.append("Recuperación: ").append(Math.round(v[2]/v[1]*100)).append("% · ");if(v[4]!=null)s.append("L/100 km: ").append(v[4]*100/v[0]);addHistory(s.toString());for(EditText x:e)x.setText("");toast("Registro manual guardado");}catch(Exception ex){toast("Introduce números válidos y una distancia mayor que cero");}});}
}
